using System;

namespace StdbModule;

public static partial class GermanQuotes
{
    public static class KarlMarx
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wenn wir den Stand gewählt, in dem wir am meisten für die Menschheit wirken können, dann können uns Lasten nicht niederbeugen, weil sie nur Opfer für alle sind; dann genießen wir keine arme, eingeschränkte, egoistische Freude, sondern unser Glück gehört Millionen, unsere Taten leben still, aber ewig wirkend fort, und unsere Asche wird benetzt von der glühenden Träne edler Menschen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Es ist die Kritik, die die einzelne Existenz am Wesen, die besondere Wirklichkeit an der Idee mißt.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Schuster Jakob Böhme war ein großer Philosoph. Manche Philosophen von Ruf sind nur große Schuster.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Kein Mensch bekämpft die Freiheit; er bekämpft höchstens die Freiheit der anderen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "So gut, wie jeder schreiben und lesen lernt, muss jeder schreiben und lesen dürfen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Unser Wahlspruch muss also sein: Reform des Bewusstseins nicht durch Dogmen, sondern durch Analysirung des mystischen sich selbst unklaren Bewusstseins, trete es nun religiös oder politisch auf. Es wird sich dann zeigen, dass die Welt längst den Traum von einer Sache besitzt, von dem sie nur das Bewusstsein besitzen muss, um sie wirklich zu besitzen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Erst wenn der wirkliche individuelle Mensch den abstrakten Staatsbürger in sich zurücknimmt und als individueller Mensch in seinem empirischen Leben, in seiner individuellen Arbeit, in seinen individuellen Verhältnissen, Gattungswesen geworden ist, erst wenn der Mensch seine »forces propres« als gesellschaftliche Kräfte erkannt und organisiert hat und daher die gesellschaftliche Kraft nicht mehr in der Gestalt der politischen Kraft von sich trennt, erst dann ist die menschliche Emanzipation vollbracht.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Suchen wir das Geheimniss des Juden nicht in seiner Religion, sondern suchen wir das Geheimniss der Religion im wirklichen Juden. Welches ist der weltliche Grund des Judenthums? Das praktische Bedürfniss, der Eigennutz. Welches ist der weltliche Kultus des Juden? Der Schacher. Welches ist sein weltlicher Gott? Das Geld. Nun wohl! Die Emancipation vom Schacher und vom Geld, also vom praktischen, realen Judenthum wäre die Selbstemancipation unsrer Zeit.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Aber der Mensch, das ist kein abstraktes, außer der Welt hockendes Wesen. Der Mensch, das ist die Welt des Menschen, Staat, Sozietät.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Mensch macht die Religion, die Religion macht nicht den Menschen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Aufhebung der Religion als des illusorischen Glücks des Volkes ist die Forderung seines wirklichen Glücks. Die Forderung, die Illusion über seinen Zustand aufzugeben, ist die Forderung, einen Zustand aufzugeben, der der Illusion bedarf.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Forderung, die Illusionen über seinen Zustand aufzugeben, ist die Forderung, einen Zustand aufzugeben, der der Illusionen bedarf.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Kritik der Religion ist die Voraussetzung aller Kritik.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Philosophie kann sich nicht verwirklichen ohne die Aufhebung des Proletariats, das Proletariat kann sich nicht aufheben ohne die Verwirklichung der Philosophie.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Religion ist der Seufzer der bedrängten Kreatur, das Gemüt einer herzlosen Welt, wie sie der Geist geistloser Zustände ist. Sie ist das Opium des Volkes.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Waffe der Kritik kann allerdings die Kritik der Waffen nicht ersetzen, die materielle Gewalt muss gestürzt werden durch materielle Gewalt, allein auch die Theorie wird zur materiellen Gewalt, sobald sie die Massen ergreift.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Es genügt nicht, dass der Gedanke zur Verwirklichung drängt, die Wirklichkeit muss sich selbst zum Gedanken drängen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Krieg den deutschen Zuständen! Allerdings!", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "man muss diese versteinerten Verhältnisse dadurch zum Tanzen zwingen, dass man ihnen ihre eigne Melodie vorsingt!", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wie die Philosophie im Proletariat ihre materiellen, so findet das Proletariat in der Philosophie seine geistigen Waffen", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Mensch ist denselben Gesetzen unterworfen wie die Natur. Macht und Freiheit sind identisch.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die „Idee“ blamierte sich immer, soweit sie von dem „Interesse“ unterschieden war.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Alle Mysterien, welche die Theorie zum Mystizismus verleiten, finden ihre rationelle Lösung in der menschlichen Praxis und im Begreifen dieser Praxis.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Frage, ob dem menschlichen Denken gegenständliche Wahrheit zukomme, ist keine Frage der Theorie, sondern eine praktische Frage. In der Praxis muß der Mensch die Wahrheit, das heißt die Wirklichkeit und Macht, die Diesseitigkeit seines Denkens beweisen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Philosophen haben die Welt nur verschieden interpretiert; es kömmt drauf an, sie zu verändern.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Feuerbach löst das religiöse Wesen in das menschliche Wesen auf. Aber das menschliche Wesen ist kein dem einzelnen Individuum inwohnendes Abstraktum. In seiner Wirklichkeit ist es das Ensemble der gesellschaftlichen Verhältnisse.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Kommunismus ist für uns nicht ein Zustand, der hergestellt werden soll, ein Ideal, wonach die Wirklichkeit sich zu richten haben wird. Wir nennen Kommunismus die wirkliche Bewegung, welche den jetzigen Zustand aufhebt.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Gedanken der herrschenden Klasse sind in jeder Epoche die herrschenden Gedanken, d.h. die Klasse, welche die herrschende materielle Macht der Gesellschaft ist, ist zugleich ihre herrschende geistige Macht.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Menschen sind die Produzenten ihrer Vorstellungen, Ideen pp., aber die wirklichen, wirkenden Menschen, wie sie bedingt sind durch eine bestimmte Entwicklung ihrer Produktivkräfte und des denselben entsprechenden Verkehrs bis zu seinen weitesten Formationen hinauf. Das Bewusstsein kann nie etwas Andres sein als das bewusste Sein, und das Sein der Menschen ist ihr wirklicher Lebensprozeß.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Nicht das Bewusstsein bestimmt das Leben, sondern das Leben bestimmt das Bewusstsein.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Philosophie und Studium der wirklichen Welt verhalten sich zueinander wie Onanie und Geschlechtsliebe.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Sprache entsteht, wie das Bewusstsein, erst aus dem Bedürfnis, der Notdurft des Verkehrs mit anderen Menschen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wenn in der ganzen Ideologie die Menschen und ihre Verhältnisse wie in einer Camera obscura auf den Kopf gestellt erscheinen, so geht dies Phänomen ebensosehr aus ihrem historischen Lebensprozeß hervor, wie die Umdrehung der Gegenstände auf der Netzhaut aus ihrem unmittelbar physischen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wird die Macht als die Basis des Rechts angenommen, wie es Hobbes etc. tun, so sind Recht, Gesetz pp. nur Symptom, Ausdruck anderer Verhältnisse, auf denen die Staatsmacht beruht.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die ökonomischen Kategorien sind nur die theoretischen Ausdrücke, die Abstraktionen der gesellschaftlichen Produktionsverhältnisse.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Es gibt keine Politik, die nicht gleichzeitig auch eine gesellschaftliche wäre.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "In der heutigen Gesellschaft, in der auf den individuellen Austausch basierten Industrie, ist die Produktionsanarchie, die Quelle so vieles Elends, gleichzeitig die Ursache alles Fortschritts.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Nur bei einer Ordnung der Dinge, wo es keine Klassen und keinen Klassengegensatz gibt, werden die gesellschaftlichen Evolutionen aufhören, politische Revolutionen zu sein.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wie die Ökonomen die wissenschaftlichen Vertreter der Bourgeoisklasse sind, so sind die Sozialisten und Kommunisten die Theoretiker der Klasse des Proletariats.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "An die Stelle der alten bürgerlichen Gesellschaft mit ihren Klassen und Klassengegensätzen tritt eine Assoziation, worin die freie Entwicklung eines jeden die Bedingung für die freie Entwicklung aller ist.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Arbeit der Proletarier hat durch die Ausdehnung der Maschinerie und die Teilung der Arbeit allen selbständigen Charakter und damit allen Reiz für den Arbeiter verloren.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Arbeiter haben kein Vaterland.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Geschichte aller bisherigen Gesellschaft ist die Geschichte von Klassenkämpfen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die interessierte Vorstellung, worin ihr eure Produktions- und Eigentumsverhältnisse aus geschichtlichen, in dem Lauf der Produktion vorübergehenden Verhältnissen in ewige Natur- und Vernunftgesetze verwandelt, teilt ihr mit allen untergegangenen herrschenden Klassen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die moderne Staatsgewalt ist nur ein Ausschuss, der die gemeinschaftlichen Geschäfte der ganzen Bourgeoisklasse verwaltet.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Kommunisten verschmähen es, ihre Ansichten und Absichten zu verheimlichen. Sie erklären es offen, daß ihre Zwecke nur erreicht werden können durch den gewaltsamen Umsturz aller bisherigen Gesellschaftsordnung.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Ein Gespenst geht um in Europa, das Gespenst des Kommunismus.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "In demselben Maße, in dem die Widerwärtigkeit der Arbeit wächst, nimmt daher der Lohn ab.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "In der bürgerlichen Gesellschaft ist die lebendige Arbeit nur ein Mittel, die aufgehäufte Arbeit zu vermehren. In der kommunistischen Gesellschaft ist die aufgehäufte Arbeit nur ein Mittel, um den Lebensprozeß der Arbeiter zu erweitern, zu bereichern, zu befördern.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Kapitalist sein, heißt nicht nur eine rein persönliche, sondern eine gesellschaftliche Stellung in der Produktion einzunehmen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Mit der Entwicklung der großen Industrie wird also unter den Füßen der Bourgeoisie die Grundlage selbst hinweggezogen, worauf sie produziert und die Produkte sich aneignet. Sie produziert vor allem ihren eigenen Totengräber. Ihr Untergang und der Sieg des Proletariats sind gleich unvermeidlich.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Mögen die herrschenden Klassen vor einer kommunistischen Revolution zittern. Die Proletarier haben nichts in ihr zu verlieren als ihre Ketten. Sie haben eine Welt zu gewinnen. Proletarier aller Länder, vereinigt euch!", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Nichts leichter, als dem christlichen Asketismus einen sozialistischen Anstrich zu geben. Hat das Christentum nicht auch gegen das Privateigentum, gegen die Ehe, gegen den Staat geeifert?", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Was beweist die Geschichte der Ideen anders, als daß die geistige Produktion sich mit der materiellen umgestaltet? Die herrschenden Ideen einer Zeit waren stets nur die Ideen der herrschenden Klasse.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Alle bisherigen Bewegungen waren Bewegungen von Minoritäten oder im Interesse von Minoritäten. Die proletarische Bewegung ist die selbständige Bewegung der ungeheuren Mehrheit im Interesse der ungeheuren Mehrzahl.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Arbeitslohn wird also durch dieselben Gesetze bestimmt, die den Preis jeder andern Ware bestimmen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Je rascher die Arbeiterklasse die ihr feindliche Macht, den fremden, über sie gebietenden Reichtum vermehrt und vergrößert, unter desto günstigeren Bedingungen wird ihr erlaubt, von neuem an der Vermehrung des bürgerlichen Reichtums, an der Vergrößerung der Macht des Kapitals zu arbeiten, zufrieden, sich selbst die goldnen Ketten zu schmieden, woran die Bourgeoisie sie hinter sich herschleift.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Menschen machen ihre eigene Geschichte, aber sie machen sie nicht aus freien Stücken, nicht unter selbstgewählten, sondern unter unmittelbar vorgefundenen, gegebenen und überlieferten Umständen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Tradition aller toten Geschlechter lastet wie ein Alp auf dem Gehirne der Lebenden. Und wenn sie eben damit beschäftigt scheinen, sich und die Dinge umzuwälzen, noch nicht Dagewesenes zu schaffen, gerade in solchen Epochen revolutionärer Krise beschwören sie ängstlich die Geister der Vergangenheit zu ihrem Dienste herauf, entlehnen ihnen Namen, Schlachtparole, Kostüm, um in dieser altehrwürdigen Verkleidung und mit dieser erborgten Sprache die neuen Weltgeschichtsszene aufzuführen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Anatomie des Menschen ist ein Schlüssel zur Anatomie des Affen. Die Andeutungen auf Höhres in den untergeordneten Tierarten können dagegen nur verstanden werden, wenn das Höhere selbst schon bekannt ist. Die bürgerliche Ökonomie liefert so den Schlüssel zur antiken etc. Keineswegs aber in der Art der Ökonomen, die alle historischen Unterschiede verwischen und in allen Gesellschaftsformen die bürgerlichen sehen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Gesellschaft besteht nicht aus Individuen, sondern drückt die Summe der Beziehungen, Verhältnisse aus, worin diese Individuen zueinander stehn.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Auf einer gewissen Stufe ihrer Entwicklung geraten die materiellen Produktivkräfte der Gesellschaft in Widerspruch mit den vorhandenen Produktionsverhältnissen oder, was nur ein juristischer Ausdruck dafür ist, mit den Eigentumsverhältnissen, innerhalb deren sie sich bisher bewegt hatten. Aus Entwicklungsformen der Produktivkräfte schlagen diese Verhältnisse in Fesseln derselben um. Es tritt dann eine Epoche sozialer Revolution ein. Mit der Veränderung der ökonomischen Grundlage wälzt sich der ganze ungeheure Überbau langsamer oder rascher um.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die bürgerlichen Produktionsverhältnisse sind die letzte antagonistische Form des gesellschaftlichen Produktionsprozesses, antagonistisch nicht im Sinn von individuellem Antagonismus, sondern eines aus den gesellschaftlichen Lebensbedingungen der Individuen hervorwachsenden Antagonismus, aber die im Schoß der bürgerlichen Gesellschaft sich entwickelnden Produktivkräfte schaffen zugleich die materiellen Bedingungen zur Lösung dieses Antagonismus. Mit dieser Gesellschaftsformation schließt daher die Vorgeschichte der menschlichen Gesellschaft ab.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Eine Gesellschaftsformation geht nie unter, bevor alle Produktivkräfte entwickelt sind, für die sie weit genug ist, und neue höhere Produktionsverhältnisse treten nie an die Stelle, bevor die materiellen Existenzbedingungen derselben im Schoß der alten Gesellschaft selbst ausgebrütet worden sind. Daher stellt sich die Menschheit immer nur Aufgaben, die sie lösen kann, denn genauer betrachtet wird sich stets finden, daß die Aufgabe selbst nur entspringt, wo die materiellen Bedingungen ihrer Lösung schon vorhanden oder wenigstens im Prozeß ihres Werdens begriffen sind.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Es ist nicht das Bewusstsein der Menschen, das ihr Sein, sondern umgekehrt ihr gesellschaftliches Sein, das ihr Bewusstsein bestimmt.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "In der gesellschaftlichen Produktion ihres Lebens gehen die Menschen bestimmte, notwendige, von ihrem Willen unabhängige Verhältnisse ein, Produktionsverhältnisse, die einer bestimmten Entwicklungsstufe ihrer materiellen Produktivkräfte entsprechen. Die Gesamtheit dieser Produktionsverhältnisse bildet die ökonomische Struktur der Gesellschaft, die reale Basis, worauf sich ein juristischer und politischer Überbau erhebt und welcher bestimmte gesellschaftliche Bewußtseinsformen entsprechen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "In der bisherigen Geschichte der Menschheit hat wohl kein Land und kein Volk so entsetzlich unter Sklaverei, fremden Eroberungen und Unterdrückungen gelitten und so leidenschaftlich um seine Freiheit gekämpft, wie Sizilien und die Sizilianer.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Aller Mehrwert, in welcher besondern Gestalt von Profit, Zins, Rente usw. er sich später kristallisiere, ist seiner Substanz nach Materiatur unbezahlter Arbeitszeit.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "alle Wissenschaft wäre überflüssig, wenn die Erscheinungsform und das Wesen der Dinge unmittelbar zusammenfielen", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Après moi le déluge! ist der Wahlspruch jedes Kapitalisten und jeder Kapitalistennation.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Auf einer gewissen Stufe der Reife angelangt, wird die bestimmte historische Form abgestreift und macht einer höhern Platz.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Das Kapital ist verstorbne Arbeit, die sich nur vampirmäßig belebt durch Einsaugung lebendiger Arbeit und um so mehr lebt, je mehr sie davon einsaugt.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der ehemalige Geldbesitzer schreitet voran als Kapitalist, der Arbeitskraftbesitzer folgt ihm nach als sein Arbeiter; der eine bedeutungsvoll schmunzelnd und geschäftseifrig, der andre scheu, widerstrebsam, wie jemand, der seine eigne Haut zu Markt getragen und nun nichts andres zu erwarten hat als die - Gerberei.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Mehrwert ist […] ein während des Produktionsprozesses vom Arbeiter neugeschaffner Wert - festgeronnene Arbeit. Nur kostet er dem Eigner des ganzen Produkts, dem Kapitalisten, nichts.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Arbeit in weißer Haut kann sich nicht dort emanzipieren, wo sie in schwarzer Haut gebrandmarkt wird.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Gewalt ist der Geburtshelfer jeder alten Gesellschaft, die mit einer neuen schwanger geht.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die ökonomische Charaktermaske des Kapitalisten hängt nur dadurch an einem Menschen fest, dass sein Geld fortwährend als Kapital funktioniert.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Zentralisation der Produktionsmittel und die Vergesellschaftung der Arbeit erreichen einen Punkt, wo sie unverträglich werden mit ihrer kapitalistischen Hülle. Sie wird gesprengt. Die Stunde des kapitalistischen Privateigentums schlägt. Die Expropriateure werden expropriiert.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "eine Biene beschämt durch den Bau ihrer Wachszellen manchen menschlichen Baumeister. Was aber von vornherein den schlechtesten Baumeister vor der besten Biene auszeichnet, ist, dass er die Zelle in seinem Kopf gebaut hat, bevor er sie in Wachs baut. Am Ende des Arbeitsprozesses kommt ein Resultat heraus, das beim Beginn desselben schon in der Vorstellung des Arbeiters, also schon ideell vorhanden war.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Es ist mit solchen Reflexionsübungen überhaupt ein eigenes Ding. Dieser Mensch ist z.B. nur König, weil sich andere Menschen als Untertanen zu ihm verhalten . Sie glauben umgekehrt Untertanen zu sein, weil er König ist.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "In Manufaktur und Handwerk bedient sich der Arbeiter des Werkzeugs, in der Fabrik dient er der Maschine.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Manch Kapital, das heute in den Vereinigten Staaten ohne Geburtsschein auftritt, ist erst gestern in England kapitalisiertes Kinderblut.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Sklaverei, auf Basis der kapitalistischen Produktionsweise, ist ungerecht; ebenso der Betrug auf die Qualität der Ware", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Was könnte die kapitalistische Produktionsweise besser charakterisieren als die Notwendigkeit, ihr durch Zwangsgesetz von Staats wegen die einfachsten Reinlichkeits- und Gesundheitsvorrichtungen aufzuherrschen?", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wenn das Geld, nach Augier, »mit natürlichen Blutflecken auf einer Backe zur Welt kommt«, so das Kapital von Kopf bis Zeh, aus allen Poren, blut- und schmutztriefend.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Zur Verwandlung von Geld in Kapital muss der Geldbesitzer also den freien Arbeiter auf dem Warenmarkt vorfinden, frei in dem Doppelsinn, dass er als freie Person über seine Arbeitskraft als seine Ware verfügt, dass er andrerseits andre Waren nicht zu verkaufen hat, los und ledig, frei ist von allen zur Verwirklichung seiner Arbeitskraft nötigen Sachen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Behaupten die Bourgeois nicht, dass die heutige Verteilung des Eigentums ,gerecht‘ ist? Und ist sie in der Tat nicht die einzige ,gerechte‘ Verteilung auf Grundlage der heutigen Produktions-weise?", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Freiheit besteht darin, den Staat aus einem der Gesellschaft übergeordneten in ein ihr durchaus untergeordnetes Organ zu verwandeln", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Zwischen der kapitalistischen und der kommunistischen Gesellschaft liegt die Periode der revolutionären Umwandlung der einen in die andre. Der entspricht auch eine politische Übergangsperiode, deren Staat nichts andres sein kann als die revolutionäre Diktatur des Proletariats.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der gesellschaftliche Fortschritt lässt sich exakt messen an der gesellschaftlichen Stellung des schönen Geschlechts (die Häßlichen eingeschlossen).", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Was ich neu tat, war 1. nachzuweisen, dass die Existenz der Klassen bloß an bestimmte historische Entwicklungsphasen der Produktion gebunden ist; 2. dass der Klassenkampf notwendig zur Diktatur des Proletariats führt; 3. dass diese Diktatur selbst nur den Übergang zur Aufhebung aller Klassen und zur klassenlosen Gesellschaft bildet.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Analysen des großen Denkers waren vielfach richtig. Teile seines Instrumentariums und seiner Methode sind auf faszinierende Weise modern geblieben. Seine Antworten erwiesen sich vielfach als falsch, seine Hoffnungen als trügerisch.", Author = "Willy Brandt" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Der Koran und die auf ihm fußende muselmanische Gesetzgebung reduzieren Geographie und Ethnographie der verschiedenen Völker auf die einfache und bequeme Zweiteilung in Gläubige und Ungläubige. Der Ungläubige ist 'harby', d.h. der Feind. Der Islam ächtet die Nation der Ungläubigen und schafft einen Zustand permanenter Feindschaft zwischen Muselmanen und Ungläubigen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Befreiung der Arbeiterklasse muß das Werk der Arbeiterklasse selbst sein. Wir können also nicht zusammengehn mit Leuten, die es offen aussprechen, daß die Arbeiter zu ungebildet sind, sich selbst zu befreien, und erst von oben herab befreit werden müssen, durch philanthropische Groß- und Kleinbürger.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Bürokratie gilt sich selbst als der letzte Endzweck des Staates.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Gesellschaft findet nun einmal nicht ihr Gleichgewicht, bis sie sich um die Sonne der Arbeit dreht.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Revolutionen sind die Lokomotiven der Geschichte.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Wahlphilosophie der Parlamentskandidaten besteht demnach einfach darin, dass sie ihrer linken Hand erlauben, nicht zu wissen, was ihre rechte Hand tut, und so waschen sie beide Hände in Unschuld. Ihre Hosentaschen zu öffnen, keine Fragen zu stellen und an die allgemeine Tugend der Menschheit zu glauben - das dient ihren Absichten am allerbesten.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Ehe das Proletariat seine Siege auf Barrikaden und in Schlachtlinien erficht, kündet es die Ankunft seiner Herrschaft durch eine Reihe intellektueller Siege an.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Es ist Aufgabe der Internationalen Arbeiterassoziation, die spontanen Bewegungen der Arbeiterklasse zu vereinigen und zu verallgemeinern, doch nicht, ihnen irgendein doktrinäres System zu diktieren oder aufzudrängen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Ist die Konstruktion der Zukunft und das Fertigwerden für alle Zeiten nicht unsere Sache, so ist desto gewisser, was wir gegenwärtig zu vollbringen haben, ich meine die rücksichtslose Kritik alles Bestehenden, rücksichtslos sowohl in dem Sinne, daß die Kritik sich nicht vor ihren Resultaten fürchtet und ebensowenig vor dem Konflikte mit den vorhandenen Mächten.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Setze den Menschen als Menschen und sein Verhältnis zur Welt als ein menschliches voraus, so kannst du Liebe nur gegen Liebe austauschen, Vertrauen nur gegen Vertrauen etc. Wenn du die Kunst genießen willst, mußt du ein künstlerisch gebildeter Mensch sein; wenn du Einfluß auf andre Menschen ausüben willst, mußt du ein wirklich anregend und fördernd auf andere Menschen wirkender Mensch sein. Jedes deiner Verhältnisse zum Menschen – und zu der Natur – muß eine bestimmte, dem Gegenstand deines Willens entsprechende Äußrung deines wirklichen individuellen Lebens sein. Wenn du liebst, ohne Gegenliebe hervorzurufen, d.h., wenn dein Lieben als Lieben nicht die Gegenliebe produziert, wenn du durch deine Lebensäußrung als liebender Mensch dich nicht zum geliebten Menschen machst, so ist deine Liebe ohnmächtig, ein Unglück.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Anarchie, das ist das große Paradepferd ihres Meisters Bakunin, der von allen sozialistischen Systemen nur die Aufschriften genommen hat.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Ein sehr tiefgründiger, doch etwas phantasiereicher Erforscher der Bewegungsgesetze der Menschheit.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Hegel bemerkt irgendwo, daß alle großen weltgeschichtlichen Tatsachen und Personen sich sozagen zweimal ereignen. Er hat vergessen hinzuzufügen: das eine Mal als Tragödie, das andere Mal als Farce. Caussidière für Danton, Louis Blanc für Robespierre, die Montagne von 1848-1851 für die Montagne von 1793-1795, der Neffe für den Onkel. Und dieselbe Karikatur in den Umständen, unter denen die zweite Auflage des achtzehnten Brumaire herausgegeben wird!", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Ricardo zeigt uns die wirkliche Bewegung der bürgerlichen Produktion, die den Wert konstituiert.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Sie haben – ich weiß nicht, ob absichtlich – in diesen Schriften dem Sozialismus eine philosophische Grundlage gegeben, und die Kommunisten haben diese Arbeiten auch sogleich in dieser Weise verstanden.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wenn der Engländer die Menschen in Hüte verwandelt, so verwandelt der Deutsche die Hüte in Ideen. Der Engländer ist Ricardo, der reiche Bankier und ausgezeichnete Ökonom. Der Deutsche ist Hegel, simpler Professor der Philosophie an der Universität zu Berlin.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wenn du nur für einen Tag oder zwei dagewesen wärst, hättest du genug Material anlegen können um für ein ganzes Jahr zu lachen. Darum war ich so bestrebt dich hier zu haben. So eine Gelegenheit bekommt man nicht jeden Tag geboten.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Wenn Widerstand gegen die Macht der Sklavenhalter die maßvolle Losung Ihrer ersten Wahl war, so ist Tod der Sklaverei! der triumphierende Schlachtruf Ihrer Wiederwahl. [...] Die Arbeiter Europas [...] betrachten es als ein Wahrzeichen der kommenden Epoche, daß Abraham Lincoln, dem starksinnigen, eisernen Sohn der Arbeiterklasse, das Los zugefallen ist, sein Vaterland durch den beispiellosen Kampf für die Erlösung einer geknechteten Race und für die Umgestaltung der sozialen Welt hindurchzuführen.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Das Vieh glaubt an den zukünftigen „Staat der Demokratie“! Unterderhand ist das bald das konstitutionelle England, bald die bürgerlichen Vereinigten Staaten, bald die elende Schweiz. Von revolutionärer Politik hat „es“ keine Ahnung.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Philosophen haben die Welt nur verschieden interpretiert; es kommt aber darauf an, sie zu verändern.", Author = "Karl Marx" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Das ,Kapital' wird mir nicht einmal so viel einbringen, als mich die Zigarren gekostet, die ich beim Schreiben geraucht.", Author = "Paul Lafargue" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Kinder müssen die Eltern erziehen.", Author = "Paul Lafargue" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Die Wissenschaft soll kein egoistisches Vergnügen sein: diejenigen, welche so glücklich sind, sich wissenschaftlichen Zwecken widmen zu können, sollen auch die ersten sein, welche ihre Kenntnisse in den Dienst der Menschheit stellen.", Author = "Paul Lafargue" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Karl_Marx", Text = "Für die Welt arbeiten.", Author = "Paul Lafargue" },
        };
    }
}